namespace Aegis.Cafeteria.PersistenceTests;
using Aegis.Cafeteria.Infrastructure.Configuration; using Aegis.Cafeteria.Infrastructure.Persistence; using Microsoft.Data.Sqlite; using Microsoft.EntityFrameworkCore; using Microsoft.Extensions.Logging.Abstractions;
public sealed class LocalSchemaBaselineTests
{
 [Fact] public async Task NewDatabase_CreatesCompleteV73LocalOnlySchema(){var file=SqliteTestDatabase.CreatePath("v73-schema");try{SqliteTestDatabase.Delete(file);var factory=new LocalDbContextFactory(DbContextOptionsFactory.CreateLocal(new CafeteriaPersistenceOptions{LocalSqliteConnectionString=$"Data Source={file}"}));await new PersistenceInitializer(factory,NullLogger<PersistenceInitializer>.Instance).InitializeLocalAsync();await using var db=factory.CreateDbContext();var schema=Assert.Single(await db.LocalSchemaInfo.ToListAsync());Assert.Equal(73,schema.SchemaVersion);Assert.Equal("v73",schema.ProductVersion);foreach(var table in new[]{"Customers","CustomerIdentifiers","Products","Orders","FfpLedgerOutbox","CafeteriaRatePolicy","MonthlyCreditAllocations","WeeklySummaryDispatches","ManagementEventInbox"})Assert.True(await TableExists(file,table));foreach(var removed in new[]{"CustomerFundingProfiles","Outbox","SyncState","Inbox","ChangeJournal"})Assert.False(await TableExists(file,removed));}finally{SqliteTestDatabase.Delete(file);}}
 [Fact] public async Task ExistingNonV67Database_IsRejectedAndNeverDeleted(){var file=SqliteTestDatabase.CreatePath("legacy");try{await using(var c=new SqliteConnection($"Data Source={file}")){await c.OpenAsync();var cmd=c.CreateCommand();cmd.CommandText="CREATE TABLE Orders(Id TEXT PRIMARY KEY); INSERT INTO Orders VALUES('keep-me');";await cmd.ExecuteNonQueryAsync();}var factory=new LocalDbContextFactory(DbContextOptionsFactory.CreateLocal(new CafeteriaPersistenceOptions{LocalSqliteConnectionString=$"Data Source={file}"}));var ex=await Assert.ThrowsAsync<InvalidOperationException>(()=>new PersistenceInitializer(factory,NullLogger<PersistenceInitializer>.Instance).InitializeLocalAsync());Assert.Contains("manually",ex.Message,StringComparison.OrdinalIgnoreCase);Assert.True(File.Exists(file));}finally{SqliteTestDatabase.Delete(file);}}
 private static async Task<bool> TableExists(string file,string table){await using var c=new SqliteConnection($"Data Source={file}");await c.OpenAsync();var cmd=c.CreateCommand();cmd.CommandText="SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name=$n";cmd.Parameters.AddWithValue("$n",table);return (long)(await cmd.ExecuteScalarAsync())! == 1L;}
}
